SELECT COUNT(*), COUNT(*) FILTER (WHERE policy_exception_flag), ROUND(100.0*COUNT(*) FILTER (WHERE policy_exception_flag)/COUNT(*),2), (SELECT policy_exception_reason FROM loan_application WHERE decision='Approved' AND policy_exception_flag AND application_date >= DATE '2021-01-01' AND application_date < DATE '2022-01-01' GROUP BY 1 ORDER BY COUNT(*) DESC, 1 LIMIT 1) FROM loan_application WHERE decision='Approved' AND application_date >= DATE '2021-01-01' AND application_date < DATE '2022-01-01'
